def mk(agent, movers=(), rewards=(), obstacles=(), prev=None):
    x=np.zeros(500)
    for r in range(10):
        for c in range(10):
            if r in (0,9) or c in (0,9):
                x[(r*10+c)*5+3]=1.0          # wall border in obstacle channel
    def s(cell,ch):
        x[(cell[0]*10+cell[1])*5+ch]=1.0
    if agent: s(agent,0)
    for m in movers: s(m,1)
    for r in rewards: s(r,2)
    for o in obstacles: s(o,3)
