import numpy as np

def obs(agent, rewards=(), movers=(), obstacles=(), prev=()):
    x = np.zeros(500)
    for r in range(10):
        for c in range(10):
            if r in (0, 9) or c in (0, 9):
                x[(r*10+c)*5+3] = 1.0          # border walls -> channel 3
    def s(p, ch): x[(p[0]*10+p[1])*5+ch] = 1.0
    s(agent, 0)
    for p in rewards:   s(p, 2)
    for p in movers:    s(p, 1)
    for p in obstacles: s(p, 3)
    for p in prev:      s(p, 4)
    return x

